mapper.select:
SELECT tracing_row.id, tracing_row.user_id, a.nickname, a.username, a.email, tracing_row.status, tracing_row.turn_count, tracing_row.first_user_question, tracing_row.last_agent_answer, tracing_row.trace_count, tracing_row.full_observation_count, tracing_row.processed_at FROM ( SELECT t.id, () AS user_id, t.status, COALESCE(JSON_LENGTH(t.llm_analysis_json, '$.turns'), 0) AS turn_count, COALESCE( JSON_UNQUOTE(JSON_EXTRACT(t.llm_analysis_json, '$.turns[0].userQuestion')), '' ) AS first_user_question, CASE WHEN COALESCE(JSON_LENGTH(t.llm_analysis_json, '$.turns'), 0) > 0 THEN COALESCE( JSON_UNQUOTE(JSON_EXTRACT( t.llm_analysis_json, CONCAT( '$.turns[', JSON_LENGTH(t.llm_analysis_json, '$.turns') - 1, '].agentAnswer' ) )), '' ) ELSE '' END AS last_agent_answer, t.trace_count, t.full_observation_count, t.processed_at FROM langfuse_session_tracing t WHERE t.tenant_id = #{tenantId} AND t.enabled = 1
AND JSON_SEARCH( t.envelope_json, 'one', #{query.userId}, NULL, '$.observations[*].userId' ) IS NOT NULL
AND t.status = #{query.status}
) tracing_row LEFT JOIN account a ON CAST(a.id AS CHAR) = tracing_row.user_id AND a.enabled = 1 ORDER BY tracing_row.processed_at DESC, tracing_row.id DESC
